# Add discovery links to existing hubs; preserve all other content.
for target in ['guides/index.html','blog/index.html','hair-services-pittsburgh/index.html']:
    f=R/target;s=f.read_text()
    s=re.sub(r'<!-- cc:saloncomparisons -->.*?<!-- /cc:saloncomparisons -->','',s,flags=re.S)
    block='<section class="archive-body" aria-labelledby="salon-comparisons"><h2 id="salon-comparisons">Compare Pittsburgh salon options</h2><p><a href="/guides/pittsburgh-salon-alternatives">Explore local salon comparisons and alternatives</a>, or prepare with our <a href="/guides/switching-hair-salons-pittsburgh">switching salons checklist</a>.</p></section>'
    wrapped='<!-- cc:saloncomparisons -->'+block+'<!-- /cc:saloncomparisons -->'
    if '</main>' in s:s=s.replace('</main>',wrapped+'</main>',1)
    else:s=s.replace('<footer',wrapped+'<footer',1)
    assert wrapped in s,target
    if target=='guides/index.html':
        desc='Plan your Pittsburgh salon visit with service comparisons, local salon alternatives, booking checklists and guides from Craft Collective.'
        for kind,name in [('name','description'),('property','og:description')]:
            s=re.sub(r'(<meta '+kind+'="'+name+r'" content=")[^"]*(")',lambda m:m[1]+desc+m[2],s)
    f.write_text(s)

NS='http://www.sitemaps.org/schemas/sitemap/0.9';ET.register_namespace('',NS)
f=R/'site-pages-sitemap.xml';tree=ET.parse(f);root=tree.getroot()
known={e.text for e in root.findall('.//{'+NS+'}loc')}
for r in records:
    if D+r['path'] not in known:
        e=ET.SubElement(root,'{'+NS+'}url');ET.SubElement(e,'{'+NS+'}loc').text=D+r['path'];ET.SubElement(e,'{'+NS+'}lastmod').text='2026-10-01'
tree.write(f,encoding='UTF-8',xml_declaration=True)
(R/'scripts/salon-comparisons-manifest.json').write_text(json.dumps({'pages':records,'source_date':'2026-10-01','sources':['https://www.studiorawelite.com/','https://www.copaceticpgh.com/','https://www.copaceticpgh.com/color','https://www.salon13.net/contact/','https://www.salon13.net/our-team/','https://bloombeautyparlor.com/']},indent=2)+'\n')
print(json.dumps(records,indent=2))
